import itertools, math, random, struct
rng=random.Random(20261106); edges=(0.,3600.,86400.,604800.)
f32=lambda x: struct.unpack('f',struct.pack('f',x))[0]

def encode(events,target,fp=False):
    n=[0]*64;s=[0.]*64;tc,tb=target
    for c,b,t,a,valid in events:
        if not valid: continue
        g=int(tc>0 and c>0 and c==tc)+2*int(tb>0 and b>0 and b==tb)
        k=int(a>=3600)+int(a>=86400)+int(a>=604800);i=16*g+4*(t-1)+k
        if fp:
            a=f32(a)
            if k<3:
                u=f32(f32(f32(math.log1p(a))-f32(math.log1p(edges[k])))/f32(f32(math.log1p(edges[k+1]))-f32(math.log1p(edges[k]))))
            else:u=f32(f32(a-604800.)/max(a,604800.))
        elif k<3:u=(math.log1p(a)-math.log1p(edges[k]))/(math.log1p(edges[k+1])-math.log1p(edges[k]))
        else:u=(a-604800)/a
        n[i]+=1;s[i]=f32(s[i]+min(1.,max(0.,u))) if fp else s[i]+min(1.,max(0.,u))
    if fp:
        h=[f32(f32(math.log1p(x))/f32(math.log(129))) for x in n];m=[f32(x/max(y,1)) for x,y in zip(s,n)]
        return [f32(x*f32(f32(2*y)-1)) for x,y in zip(h,m)],[f32(x*y) for x,y in zip(h,m)],h,n
    h=[math.log1p(x)/math.log(129) for x in n];m=[x/max(y,1) for x,y in zip(s,n)]
    return [x*(2*y-1) for x,y in zip(h,m)],[x*y for x,y in zip(h,m)],h,n

def oracle(events,target):
    result=[[],[],[],[]];tc,tb=target
    for g,t,k in itertools.product(range(4),range(1,5),range(4)):
        ages=[]
        for c,b,action,a,valid in events:
            if not valid: continue
            group=(int(c"'!=0 and tc!=0 and c==tc),int(b!=0 and tb!=0 and b==tb))
            if group!=(g%2,g//2) or action!=t or a<edges[k] or (k<3 and a>=edges[k+1]):continue
            ages.append(a)
        if k<3:values=[math.log((a+1)/(edges[k]+1))/math.log((edges[k+1]+1)/(edges[k]+1)) for a in ages]
        else:values=[1-604800/a for a in ages]
        n=len(ages);h=math.log1p(n)/math.log(129);m=math.fsum(values)/max(1,n)
        for arr,x in zip(result,[h*(2*m-1),h*m,h,n]):arr.append(x)
    return result

stats={'"'cases':0,'direct_max':0.,'reverse_max':0.,'affine_max':0.,'emulated_float32_max':0.}
def gap(a,b):return max(abs(x-y) for xs,ys in zip(a,b) for x,y in zip(xs,ys))
def check(events,target):
    a=encode(events,target);b=oracle(events,target)
    stats['direct_max']=max(stats['direct_max'],gap(a,b));assert gap(a,b)<1e-12
    r=encode(events[::-1],target);stats['reverse_max']=max(stats['reverse_max'],gap(a,r));assert gap(a,r)<1e-12
    affine=max(abs(c-2*u+h) for c,u,h in zip(*a[:3]));stats['affine_max']=max(stats['affine_max'],affine);assert affine<1e-12
    assert all(abs(c)<=h+1e-14 and 0<=u<=h+1e-14 for c,u,h in zip(*a[:3]))
    assert sum(a[3])==sum(e[-1] for e in events)
    assert encode(events+[(1,1,1,float('nan'),False),(0,0,4,-999.,False)],target)==a
    ren=lambda x:x+7 if x else 0
    assert encode([(ren(c),ren(b),t,age,v) for c,b,t,age,v in events],tuple(map(ren,target)))==a
    fg=gap(a[:3],encode(events,target,True)[:3]);stats['emulated_float32_max']=max(stats['emulated_float32_max'],fg);assert fg<1e-5
    stats['cases']+=1
states=[(c,b,t,[0.,3599.,3600.,86399.,86400.,604799.,604800.,1209600.][(4*(c-1)+t-1)%8],True) for c,b in [(1,1),(1,2),(2,1),(2,2)] for t in range(1,5)]
for n in range(4):
    for seq in itertools.product(states,repeat=n):check(list(seq),(1,1))
ages=[0.,1.,3599.,3600.,3601.,86399.,86400.,86401.,604799.,604800.,604801.,1209600.,1e9,1e20,1e30]
for a in ages:
    for c,b in [(0,0),(1,0),(0,1),(1,1),(1,2),(2,1),(2,2)]:
        for action in range(1,5):
            for target in [(0,0),(1,1),(2,2)]:
                check([(c,b,action,a,True)],target);check([(c,b,action,a,True)]*128,target)
for _ in range(400):
    events=[]
    for i in range(rng.randrange(129)):
        age=rng.choice(ages) if rng.random()<.5 else f32(math.exp(rng.uniform(0,24))-1)
        events.append((rng.randrange(3),rng.randrange(3),rng.randrange(1,5),age,rng.random()>.2))
    check(events,(rng.randrange(3),rng.randrange(3)))
a=encode([(1,1,1,x,True) for x in (45000.,50000.)],(1,1));b=encode([(1,1,1,x,True) for x in (55000.,60000.)],(1,1))
assert a[2]==b[2] and a[0]"'!=b[0] and a[1]!=b[1]
assert [int(math.log2(x+1))+1 for x in (45000.,50000.)]==[int(math.log2(x+1))+1 for x in (55000.,60000.)]
print(stats)
print('"'Witness centered gap',gap(a[:1],b[:1]),'uncentered gap',gap(a[1:2],b[1:2]),'histogram gap0')
print('Passed scalar algebra/invariance checks. Threshold1e-5 for emulated serial float32; no model changes to pass. This does not execute Torch/CUDA or verify gradients/logits.')
PY"

